const form=document.getElementById("delayForm"),result=document.getElementById("result");form&&form.addEventListener("submit",s=>{s.preventDefault();const t=parseFloat(document.getElementById("sum").value)||0,e=parseFloat(document.getElementById("rate").value)||0,a=parseInt(document.getElementById("days").value,10)||0,n=parseInt(document.getElementById("div").value,10)||150;if(t<=0||e<=0||a<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите сумму, ставку и дни больше нуля.</p>';return}const l=t*(e/100/n)*a;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Сумма долга</span><span class="val">${fmt(t)} ₽</span></div>
        <div class="item"><span>Ставка / коэффициент</span><span class="val">${fmt(e)}% ÷ ${n}</span></div>
        <div class="item"><span>Дней просрочки</span><span class="val">${a}</span></div>
        <div class="item total"><span>Компенсация</span><span class="val">${fmt(l)} ₽</span></div>
      </div>
    `});function fmt(s){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(s)}
